class Solution {
public:
    Node* findRoot(vector<Node*> tree) {
        int value = 0;
        for (Node* node : tree) {
            value ^= node->val;
            for (Node* child : node->children) {
                value ^= child->val;
            }
        }
        for (Node* node : tree) {
            if (node->val == value) {
                return node;
            }
        }
        return nullptr;
    }
};
